/**
 * The shape of Deploy/OURONET-REGISTRY.json.
 *
 * Generated by REPL/tools/_registry.py in the Pact repo, which reads the CHAIN via
 * `describe-module` and falls back to the sources only for modules not yet deployed. So the
 * authority here is what is CALLABLE, not what someone intends to deploy.
 */

/** One parameter, in declaration order. Position is the calling convention. */
export interface Param {
  name: string;
  type: string;
}

/** How a call executes -- see `ExecutionMode`. */
export type ExecutionMode =
  /** the provided inputs suffice; nothing is read off-chain first */
  | "direct"
  /** ONE transaction, but a preflight read supplies some argument */
  | "indirect-single"
  /** a preflight is cut into slices, one per transaction, ORDER-INDEPENDENT */
  | "indirect-parallel"
  /** a preflight reports progress; each call advances a stored cursor. STRICTLY ORDERED */
  | "indirect-sequential"
  /** multi-transaction by CONTINUATION: step 0 on submit, the rest are `cont` payloads */
  | "defpact";

export interface FedParam {
  param: string;
  type: string;
  /** the read(s) that produce this value. A client cannot construct it. */
  producedBy: string[];
  /** for a fed slice, what cuts the preflight's output into per-transaction slices */
  slicedBy: string[] | null;
}

export interface Continuation {
  payload: "cont";
  pactId: string;
  step: string;
  rollback: string;
  /** empty for every defpact in Ouronet: no step reads client input */
  data: Record<string, never>;
  dataNote: string;
  /** the surprise: continuations are NOT gas-sponsored. Step 0 is. */
  gas: string;
}

/**
 * HOW A CALL MAY BE SPLIT ACROSS TRANSACTIONS.
 *
 * Present only when the operation has actually been READ and a judgement recorded. ABSENCE MEANS
 * DO NOT SPLIT: a consumer that finds no `partition` sends one transaction or refuses, and never
 * guesses. That default is the safety property -- a wrong permission silently converts an ATOMIC
 * operation into a partially-applied one, and no assertion downstream can detect it.
 *
 * The block is hand-authored (`Deploy/OURONET-REGISTRY.authored.json`) for the same reason ghost
 * values are: a contract states that a parameter is a list, never that cutting that list in half
 * yields the same outcome as one call. The generator's `--check` verifies the SHAPE of the claim
 * against the signature -- axis and lockstep names exist and are list-typed, no orphans -- but the
 * semantic half is a human reading and is attributed as one, in `reason`.
 *
 * WHETHER a split is NEEDED is a different question, answered by simulation and not by this field.
 * Gas is state-dependent; splittability is not.
 */
export interface Partition {
  /**
   * WHICH KIND OF SPLIT THIS IS — read this first; the rest of the block depends on it.
   *
   * `list`          The list is an ARGUMENT. A client cuts it, the piece count comes from
   *                 MEASUREMENT and is unbounded, and `axis`/`lockstep`/`inner`/`shape` describe
   *                 how. Use `splitCall` / `splitCallByCapacity`.
   * `cursor`        The work is list-SHAPED but the list lives in chain STATE — the entrypoint
   *                 takes no list at all, so there is nothing for a client to cut. `via` names a
   *                 pager that advances stored progress: unbounded calls, STRICTLY SEQUENTIAL
   *                 (two race the cursor), repeated until the `progress` reads say done.
   * `architectural` The operation decomposes into ORDERED PHASES intrinsic to itself, each
   *                 depending on what the last left behind. That is continuation state, so a
   *                 defpact is its only expression and `via` names it. DERIVED by inverting that
   *                 defpact's own `preferInstead`.
   *
   * WHY A DEFPACT CANNOT CARRY A LIST SPLIT (owner ruling, 2026-10-27 — the distinction this
   * taxonomy was missing): a defpact's step count is FIXED by its definition, while a list has
   * no fixed length. So a defpact expresses a decomposition whose piece-count is INTRINSIC to
   * the operation, and it cannot express one whose piece-count comes from measuring a list — a
   * 2-step twin caps the work at two steps forever. Two AQP defpacts were written for exactly
   * that mistake and are recorded as superseded by cursor pagers rather than offered as routes.
   */
  kind: "list" | "cursor" | "architectural";
  /**
   * `partition` -- cutting `axis` yields pieces whose combined effect equals the single call.
   *               One round, order-independent, submit them all at once.
   * `reduction`  -- each piece yields a NEW intermediate that must be fed back in (merging 860
   *               nonces 123 at a time leaves 7, which are merged again). Parallel WITHIN a
   *               round, strictly sequential BETWEEN rounds, and the next round's arguments do
   *               not exist until the current one lands on chain.
   *
   * Two members rather than one boolean, deliberately: this repo has already paid for that
   * conflation once, when the `p` recipe suffix was overloaded to mean "multi-transaction"
   * rather than "parallel" and a strictly sequential cursor pager ended up wearing a prefix
   * that promised parallel safety (StoicSyntax-Prefixes.md, CORRECTION 2026-09-14).
   */
  shape?: "partition" | "reduction";
  /** `list` only — the list-typed parameter that is cut. Checked to exist and be a list. */
  axis?: string;
  /** `cursor` / `architectural` only — the entrypoint that carries the split. */
  via?: string;
  /** `cursor` only — the reads that report progress. Must equal the pager's own preflight. */
  progress?: string[];
  /** `architectural` only — the twin's step count, checked against the twin itself. */
  steps?: number;
  /**
   * `list` only — a parameter whose VALUE MUST NOT BE SPLIT across batches. Every element
   * sharing a `groupBy` value stays in ONE transaction.
   *
   * The AQP vacate slices are what this exists for. Their per-beneficiary unwind is UNGATED and
   * is fed that slice's partial sum: two of its six legs are delta-based and add up correctly,
   * but the other four are a settle triple that would then run once per SLICE instead of once
   * per BENEFICIARY. The sibling DRAIN path gates that same triple behind
   * `UR_AQP|UserUnn == 0` precisely so it fires once; vacate does not, which is the evidence
   * that its design assumes a beneficiary never spans two slices.
   *
   * So this constrains WHERE a cut may fall, not whether one may happen. Checked to be the axis
   * itself or one of its lockstep companions — a key not positional against the axis cannot
   * define a boundary in it.
   */
  groupBy?: string;
  /**
   * Parameters POSITIONAL against `axis`, which must be cut WITH it. The failure mode here is
   * silent rather than loud: two arrays that line up by LENGTH and are misaligned move the wrong
   * amount to the wrong place, and the contract has no way to object.
   */
  lockstep?: string[];
  /**
   * A SECOND SPLITTABLE LEVEL, present when the axis's companions are NESTED lists.
   *
   * `C_MultiBulkTransfer` is the clearest case: `id-lst` is a token list, and for each token
   * `executee-array[i]` is that token's whole recipient list. Cutting the outer axis yields
   * fewer TOKENS per transaction, and a single token with 1,000 recipients can still be far too
   * large -- so the inner level cuts that one token's recipient list as well. A manifest of 100
   * tokens with 1,000 recipients each is 100,000 legs and needs both levels to be expressible.
   *
   * `axis` and `lockstep` here name OUTER parameters whose per-element arrays are cut in step;
   * every one must be a nested list (`[[...]]`) and must already be the outer axis or one of its
   * outer companions, so the two levels cannot describe unrelated parameters. The generator
   * checks exactly that.
   */
  inner?: {
    axis: string;
    lockstep?: string[];
    note: string;
  };
  /** `reduction` only, and required there -- how the next round's input is obtained. */
  rounds?: string;
  /** why this split is sound. An unexplained permission to split is not one. */
  reason: string;
}

export interface Execution {
  mode: ExecutionMode;
  shape?: string;
  note: string;
  /** reads to run BEFORE building the transaction */
  preflight?: string[] | null;
  fedParams?: FedParam[] | null;
  preflightUnresolved?: boolean;
  /** defpact only */
  pact?: string;
  steps?: number;
  rollbackSteps?: number;
  inputs?: ExecutionMode;
  continuation?: Continuation;
  /** false when a supported single-transaction twin exists -- see preferInstead */
  supported?: boolean;
  preferInstead?: string;
  supportedNote?: string;
  /** the reader that computes this call's required capabilities */
  capabilityPreflight?: string;
  /** how this call may be split across transactions. ABSENT MEANS DO NOT SPLIT -- see `Partition`. */
  partition?: Partition;
}

export interface OwnershipClause {
  /** the account, or "owner of `<entity>`" when a lookup is needed */
  account: string;
  via: "parameter" | "reader";
  /** ALWAYS = unconditional. CONDITIONAL = binds on one branch only. */
  when: "ALWAYS" | "CONDITIONAL";
  meaning: string;
  reader?: string;
  subject?: string;
  conditionalOn?: string;
}

export interface Ownership {
  resolved: boolean;
  requires?: OwnershipClause[];
  /** subjects found deeper in the call tree that could not be mapped to a parameter */
  unmapped?: string[] | null;
  unmappedNote?: string;
  reason?: string;
}

export interface Sponsorship {
  /** true, false, or "step-0-only" for a defpact whose continuations the customer pays */
  sponsored: boolean | "step-0-only";
  sponsor?: string;
  cap?: string;
  capArgs?: Param[];
  suppliedBy?: string | null;
  conditional?: string | null;
  stepsNote?: string;
}

export interface ExternalCaps {
  required: true;
  /** the READER that computes the capability arguments -- it IS the formula */
  computedBy: string;
  readerParams: Param[];
  /** reader parameter -> this entrypoint's parameter, or a note when client-supplied */
  argsFrom: Record<string, string>;
  returns: string;
  format: string;
  parse: string;
  attachTo: string;
  note: string;
}

/** Where a single ghost value may be used. Absent field = permitted. */
export interface GhostUse {
  /** false = MUST NOT be prefilled into an input that can reach a signed transaction. */
  zbom?: boolean;
  /** false = must not be rendered at all. */
  tooltip?: boolean;
  /** render this string instead of the value (the submittable and readable forms differ). */
  display?: string;
}

export interface Ghost {
  /** example arguments by parameter name. `null` means "obtain from the preflight". */
  args: Record<string, unknown>;
  source: string;
  notes?: Record<string, string>;
  /**
   * Per-parameter surface restrictions. Present ONLY for parameters that have one -- 6 of 423
   * entrypoints today, all guard-taking. An absent parameter is unrestricted.
   */
  use?: Record<string, GhostUse>;
  useNote?: string;
  unresolved?: string[];
  unresolvedNote?: string;
  warning: string;
}

export interface Entrypoint {
  params: Param[];
  /** declared return type, or null when the signature does not pin one */
  returns: string | null;
  returnsNote?: string;
  source: "deployed" | "repo-only";
  modulePath: string;
  moduleHash?: string;
  callable?: false;
  note?: string;
  ownership: Ownership;
  sponsorship: Sponsorship;
  execution: Execution;
  externalCaps?: ExternalCaps;
  ghost: Ghost;
  /** the INFO_ reader that prices this call */
  preview?: string;
  previewVia?: string;
  previewMissing?: string;
}

export interface Preview {
  params: Param[];
  returns: string | null;
  source: "deployed" | "repo-only";
  modulePath: string;
  moduleHash?: string;
}

export interface Divergence {
  module: string;
  function: string;
  deployed: Param[] | null;
  repo: Param[] | null;
}

export interface RegistryDoc {
  note: string;
  namespace: string;
  generatedFrom: "chain+repo" | "repo-only";
  entrypoints: Record<string, Entrypoint>;
  previews: Record<string, Preview>;
  /** bare names that resolve to more than one module -- ALWAYS address MODULE.function */
  nameCollisions: Record<string, { module: string; mode: ExecutionMode }[]>;
  divergences: Divergence[];
  notDeployed: string[];
  surfaceHash: string;
}
